def compute(vars):
    interest_rate_swaps_millions = vars["v1"] * 1000
    foreign_currency_hedges_millions = vars["v2"]

    if foreign_currency_hedges_millions == 0:
        return None

    value = interest_rate_swaps_millions / foreign_currency_hedges_millions
    return {
        "value": value,
        "trace": {
            "interest_rate_swaps_millions": interest_rate_swaps_millions,
            "foreign_currency_hedges_millions": foreign_currency_hedges_millions,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
